    }

    function resetToolState() {
      TOOL_STATE.freeChat = true;
      TOOL_STATE.deepThink = false;
      TOOL_STATE.webSearch = false;
      TOOL_STATE.knowledgeQA = false;
    }

    function syncToolButtons(animatedKeys = []) {
      [...els.toolRow.querySelectorAll(".tool-pill")].forEach((button) => {
        const key = button.dataset.toolKey;
        button.classList.toggle("active", Boolean(TOOL_STATE[key]));
        if (animatedKeys.includes(key)) {
          button.classList.remove("pulse");
          void button.offsetWidth;
          button.classList.add("pulse");
          window.setTimeout(() => button.classList.remove("pulse"), 420);
        }
      });
    }

    function applyToolState(toggles = []) {
      resetToolState();
      toggles.forEach((toggle) => {
        if (toggle === "knowledgeQA") {
          TOOL_STATE.knowledgeQA = true;
          TOOL_STATE.freeChat = false;
        } else {
          TOOL_STATE[toggle] = true;
