    function pointPetToAgent(agentId) {
      const card = els.agentGrid.querySelector(`[data-agent-id="${agentId}"]`);
      if (!card) return;
      const petRect = els.digitalHuman.getBoundingClientRect();
      const cardRect = card.getBoundingClientRect();
      const dx = cardRect.left + cardRect.width / 2 - (petRect.left + petRect.width / 2);
      const dy = cardRect.top + cardRect.height / 2 - (petRect.top + petRect.height / 2);
      const angle = Math.max(-18, Math.min(18, Math.atan2(dy, dx) * 180 / Math.PI * 0.25));
      els.digitalHuman.style.setProperty("--point-angle", `${angle}deg`);
      setDigitalHumanState("executing");
      if (appState.pointTimer) window.clearTimeout(appState.pointTimer);
