    }

    startSpeech(text, duration) {
      this.speechDuration = Math.max(700, duration || 1400);
      this.speechEndsAt = performance.now() + this.speechDuration;
      this.speechSeed = hashText(text) % 97;
    }

    stopSpeech() {
      this.speechEndsAt = 0;
      this.speechDuration = 0;
    }

    setFocusFromViewport(clientX, clientY) {
      const rect = this.host.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const x = ((clientX - rect.left) / rect.width - 0.5) * 2;
      const y = ((clientY - rect.top) / rect.height - 0.5) * 2;
      this.focusTarget.x = clamp(x, -1.2, 1.2);
      this.focusTarget.y = clamp(y, -1.2, 1.2);
    }

    sampleSpeechLevel(now) {
      if (this.audio && this.audio.analyser) {
        this.audio.analyser.getByteFrequencyData(this.audio.buffer);
        let total = 0;
        for (let index = 0; index < this.audio.buffer.length; index += 1) total += this.audio.buffer[index];
        return clamp(total / (this.audio.buffer.length * 255) * 2.4, 0, 1);
      }
      if (now >= this.speechEndsAt || !this.speechDuration) return 0;
      const progress = 1 - (this.speechEndsAt - now) / this.speechDuration;
      const phrase = progress * 12.4;
      const rhythm = Math.abs(Math.sin(phrase * 2.8 + this.speechSeed * 0.06));
      const syllable = Math.abs(Math.sin(phrase * 6.3 + this.speechSeed * 0.11));
      const gate = Math.sin(phrase * 4.5 + this.speechSeed * 0.09) > -0.25 ? 1 : 0.3;
