        headX: idleWave * 2.5,
        headY: -2 + idleWave2 * 1.8,
        headRotate: idleWave * 0.03,
        eyeX: focusX * 12,
        eyeY: focusY * 8,
        blink,
        bodyLean: idleWave * 0.018,
        bodyRotate: idleWave2 * 0.028,
        torsoLift: 2 + Math.sin(now * 0.0032) * 3,
        armLUpper: -0.1 + idleWave * 0.03,
        armLLower: 0.05,
        armRUpper: 0.08 - idleWave * 0.03,
        armRLower: -0.04,
        mouthOpen: 0,
        mouthShape: 0,
        smile: 0.18,
        brow: 0.1,
        glow: 0.18
