      switch (this.state) {
        case "Observe":
          target.headX = focusX * 5;
          target.headY = -4 + focusY * 2;
          target.headRotate = focusX * 0.1;
          target.bodyLean = focusX * 0.028;
          target.bodyRotate = focusX * 0.045;
          target.torsoLift = 6;
          target.smile = 0.45;
          target.brow = 0.22;
          target.glow = 0.34;
