          target.headRotate = Math.sin(elapsed * 8) * 0.08;
          target.bodyLean = Math.sin(elapsed * 6) * 0.02;
          target.armRUpper = 0.26 + Math.sin(elapsed * 11) * 0.36;
          target.armRLower = -0.24 + Math.cos(elapsed * 11) * 0.22;
          target.armLUpper = -0.2;
          target.armLLower = 0.1;
          target.smile = 0.6;
          target.brow = 0.28;
          target.glow = 0.44;
          break;
        case "Listening":
          target.headX = focusX * 3;
          target.headY = -6;
          target.headRotate = focusX * 0.05;
          target.bodyLean = 0.04;
          target.torsoLift = 8;
          target.armLUpper = -0.18;
          target.armRUpper = 0.16;
          target.mouthOpen = 0.18;
          target.mouthShape = 0.2;
          target.smile = 0.24;
          target.brow = 0.18;
          target.glow = 0.58;
          break;
        case "Thinking":
          target.headX = 2;
          target.headY = -5;
          target.headRotate = -0.12;
          target.eyeX = -3 + Math.sin(elapsed * 2.2) * 4;
          target.eyeY = -6;
          target.armLUpper = -0.82;
          target.armLLower = 1.28;
          target.armRUpper = 0.12;
          target.armRLower = 0.1;
          target.smile = 0.08;
          target.brow = -0.2;
          target.glow = 0.28;
          break;
        case "Speaking":
          target.headX = focusX * 2;
          target.headY = -5 + Math.sin(elapsed * 8.5) * 2;
          target.headRotate = Math.sin(elapsed * 6.5) * 0.05;
          target.bodyLean = focusX * 0.015;
          target.torsoLift = 7 + Math.sin(elapsed * 7.2) * 2.5;
          target.armRUpper = 0.18 + Math.sin(elapsed * 5.4) * 0.18;
          target.armRLower = -0.12 + Math.cos(elapsed * 5.4) * 0.12;
          target.armLUpper = -0.12 + Math.sin(elapsed * 3.6) * 0.06;
          target.mouthOpen = speechLevel;
          target.mouthShape = speechLevel > 0.68 ? 1 : speechLevel > 0.38 ? 0.65 : 0.32;
