          target.brow = 0.22;
          target.glow = 0.52;
          break;
        case "Dragging":
          target.headX = focusX * 2;
          target.headY = -3;
          target.headRotate = -this.drag.tilt * 0.14;
          target.bodyLean = this.drag.tilt * 0.06;
          target.bodyRotate = this.drag.tilt * 0.22;
          target.armLUpper = -0.28 - this.drag.tilt * 0.12;
          target.armLLower = 0.24;
          target.armRUpper = 0.28 - this.drag.tilt * 0.12;
          target.armRLower = -0.2;
          target.smile = 0.16;
          target.brow = 0.1;
          target.glow = 0.26;
          break;
        case "Celebrate":
