      this.browGraphics.clear();
      this.browGraphics.moveTo(leftEye.x - 76, browBase - p.brow * 30);
      this.browGraphics.lineTo(leftEye.x + 8, browBase + p.brow * 16);
      this.browGraphics.stroke({ width: 9, color: INK, alpha: 0.88 });
      this.browGraphics.moveTo(rightEye.x - 8, browBase + p.brow * 16);
      this.browGraphics.lineTo(rightEye.x + 76, browBase - p.brow * 30);
      this.browGraphics.stroke({ width: 9, color: INK, alpha: 0.88 });

      this.eyeGraphics.clear();
      this.eyeGraphics.circle(leftEye.x + pupilOffsetX, leftEye.y + pupilOffsetY, 34);
      this.eyeGraphics.fill({ color: BLUE, alpha: 0.8 });
      this.eyeGraphics.circle(leftEye.x + pupilOffsetX, leftEye.y + pupilOffsetY, 26);
      this.eyeGraphics.fill({ color: INK, alpha: 0.9 });
      this.eyeGraphics.circle(leftEye.x + pupilOffsetX - 9, leftEye.y + pupilOffsetY - 10, 8);
      this.eyeGraphics.fill({ color: 0xffffff, alpha: 0.78 });

      this.eyeGraphics.circle(rightEye.x + pupilOffsetX, rightEye.y + pupilOffsetY, 34);
      this.eyeGraphics.fill({ color: BLUE, alpha: 0.8 });
      this.eyeGraphics.circle(rightEye.x + pupilOffsetX, rightEye.y + pupilOffsetY, 26);
      this.eyeGraphics.fill({ color: INK, alpha: 0.9 });
      this.eyeGraphics.circle(rightEye.x + pupilOffsetX - 9, rightEye.y + pupilOffsetY - 10, 8);
      this.eyeGraphics.fill({ color: 0xffffff, alpha: 0.78 });

      this.eyeGraphics.circle(leftEye.x + 48, leftEye.y - 22, 12);
      this.eyeGraphics.fill({ color: SOFT_BLUE, alpha: 0.18 + p.glow * 0.18 });
      this.eyeGraphics.circle(rightEye.x - 48, rightEye.y - 22, 12);
      this.eyeGraphics.fill({ color: SOFT_BLUE, alpha: 0.18 + p.glow * 0.18 });

      this.lidGraphics.clear();
      const lidTop = 8 + eyelidAmount * 84;
      const lidBottom = eyelidAmount * 24;
      [leftEye, rightEye].forEach((eye) => {
        this.lidGraphics.roundRect(eye.x - 92, eye.y - 88, 184, lidTop, 34);
        this.lidGraphics.fill({ color: FACE_FILL, alpha: 0.95 });
        if (lidBottom > 0.5) {
          this.lidGraphics.roundRect(eye.x - 92, eye.y + 52 - lidBottom, 184, lidBottom, 24);
          this.lidGraphics.fill({ color: FACE_FILL, alpha: 0.92 });
        }
      });

      this.mouthGraphics.clear();
      this.mouthGraphics.roundRect(mouth.x - 76, mouth.y - 36, 152, 78, 34);
      this.mouthGraphics.fill({ color: FACE_FILL, alpha: 0.76 });

      if (p.mouthOpen > 0.6) {
        this.mouthGraphics.ellipse(mouth.x, mouth.y + 8, 14 + p.mouthOpen * 20, 12 + p.mouthOpen * 24);
        this.mouthGraphics.fill({ color: INK, alpha: 0.95 });
      } else if (p.mouthShape > 0.35) {
        this.mouthGraphics.ellipse(mouth.x, mouth.y + 10, 22 + p.mouthOpen * 14, 9 + p.mouthOpen * 10);
        this.mouthGraphics.fill({ color: INK, alpha: 0.9 });
      } else {
        this.mouthGraphics.moveTo(mouth.x - 34, mouth.y + 8 - p.smile * 10);
        this.mouthGraphics.quadraticCurveTo(mouth.x, mouth.y + 18 + p.smile * 8, mouth.x + 34, mouth.y + 8 - p.smile * 10);
        this.mouthGraphics.stroke({ width: 7, color: INK, alpha: 0.92 });
      }
    }

    drawAccentGlow(p) {
      this.accentGlow.clear();
      this.accentGlow.ellipse(640, 840, 160, 54);
      this.accentGlow.fill({ color: BLUE, alpha: 0.05 + p.glow * 0.12 });
      this.accentGlow.ellipse(640, 840, 104, 28);
      this.accentGlow.fill({ color: SOFT_BLUE, alpha: 0.05 + p.glow * 0.1 });
    }

    async destroy() {
      this.destroyed = true;
      if (this.resizeObserver) this.resizeObserver.disconnect();
      if (this.app) {
        this.app.destroy(true, { children: true, texture: false });
        this.app = null;
      }
      if (this.stageHost && this.stageHost.parentNode) {
        this.stageHost.parentNode.removeChild(this.stageHost);
      }
    }
  }

  global.createHaiXiaoNanAvatarRuntime = async function createHaiXiaoNanAvatarRuntime(options) {
    const runtime = new HaiXiaoNanAvatarRuntime(options);
    return runtime.init();
  };

