    AvatarLayerManifest: "frame rectangles and anchors for avatar parts",
    AvatarParams: "frame-level parameter bag for pose and expression",
    AvatarState: ["Idle", "Observe", "Interact", "DragStart", "Dragging", "Release", "Listening", "Thinking", "Speaking", "Celebrate"],
    AvatarBehaviorEvent: ["state", "pointermove", "pointerleave", "dragstart", "dragmove", "dragend", "point", "speech", "speechEnd"],
    MotionClip: "time-boxed gesture or expression overlay"
  };
})(window);

